import { Loader2 } from "lucide-react";

interface LoadingAnalysisProps {
  type: "meal" | "body";
}

const messages = {
  meal: [
    "Analyzing your meal...",
    "Identifying ingredients...",
    "Calculating nutrition...",
    "Almost there!",
  ],
  body: [
    "Analyzing your photo...",
    "Processing measurements...",
    "Calculating estimates...",
    "Preparing results...",
  ],
};

export function LoadingAnalysis({ type }: LoadingAnalysisProps) {
  return (
    <div className="flex flex-col items-center justify-center py-16 px-4 animate-fade-in">
      <div className="relative mb-6">
        <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center">
          <Loader2 className="w-10 h-10 text-primary animate-spin" aria-hidden="true" />
        </div>
        <div className="absolute inset-0 rounded-full border-4 border-primary/20 animate-pulse" />
      </div>

      <h3 className="text-subtitle text-foreground mb-2">Analyzing...</h3>
      <p className="text-body text-muted-foreground text-center max-w-xs">
        {type === "meal" 
          ? "This takes just a few seconds ✨"
          : "Hang tight, we're processing your photo 😊"
        }
      </p>

      <div className="mt-8 flex gap-2">
        {[0, 1, 2].map((i) => (
          <div
            key={i}
            className="w-2 h-2 rounded-full bg-primary animate-pulse-gentle"
            style={{ animationDelay: `${i * 200}ms` }}
          />
        ))}
      </div>
    </div>
  );
}

import { Star, MessageCircle, Phone, Calendar } from "lucide-react";
import { Button } from "@/components/common/button";

interface TrainerCardProps {
  id: string;
  name: string;
  specialty: string;
  rating: number;
  reviewCount: number;
  pricePerSession: number;
  imageUrl?: string;
  available?: boolean;
  onViewProfile?: (id: string) => void;
  onChat?: (id: string) => void;
  onCall?: (id: string) => void;
  onBook?: (id: string) => void;
}

export function TrainerCard({
  id,
  name,
  specialty,
  rating,
  reviewCount,
  pricePerSession,
  imageUrl,
  available = true,
  onViewProfile,
  onChat,
  onCall,
  onBook,
}: TrainerCardProps) {
  return (
    <div className="fit-card-elevated space-y-4 animate-slide-up">
      <div className="flex items-start gap-4">
        {/* Avatar */}
        <div className="relative">
          {imageUrl ? (
            <img
              src={imageUrl}
              alt={`${name}, fitness coach`}
              className="w-16 h-16 rounded-2xl object-cover"
            />
          ) : (
            <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-primary/20 to-secondary/20 flex items-center justify-center">
              <span className="text-title font-display text-primary">
                {name.charAt(0)}
              </span>
            </div>
          )}
          {available && (
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-success rounded-full border-2 border-card" />
          )}
        </div>

        {/* Info */}
        <div className="flex-1 min-w-0">
          <h3 className="text-subtitle text-foreground truncate">{name}</h3>
          <p className="text-small text-muted-foreground">{specialty}</p>

          <div className="flex items-center gap-3 mt-2">
            <div className="flex items-center gap-1">
              <Star className="w-4 h-4 text-accent fill-accent" aria-hidden="true" />
              <span className="text-small font-medium text-foreground">{rating}</span>
              <span className="text-tiny text-muted-foreground">({reviewCount})</span>
            </div>
            <div className="text-small text-primary font-medium">
              ${pricePerSession}/session
            </div>
          </div>
        </div>
      </div>

      {/* Actions */}
      <div className="flex gap-2">
        <Button
          variant="primary-pill"
          size="default"
          onClick={() => onBook?.(id)}
          className="flex-1"
          aria-label={`Book a session with ${name}`}
        >
          <Calendar className="w-4 h-4" />
          Book
        </Button>
        <Button
          variant="outline"
          size="icon"
          onClick={() => onChat?.(id)}
          aria-label={`Chat with ${name}`}
        >
          <MessageCircle className="w-4 h-4" />
        </Button>
        <Button
          variant="outline"
          size="icon"
          onClick={() => onCall?.(id)}
          aria-label={`Call ${name}`}
        >
          <Phone className="w-4 h-4" />
        </Button>
      </div>
    </div>
  );
}

